// DecodeSearchRequest returns a decoder for requests sent to the notes search
// endpoint.
func DecodeSearchRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*notes.SearchPayload, error) {
	return func(r *http.Request) (*notes.SearchPayload, error) {
		var payload *notes.SearchPayload
		var (
			q        string
			notebook *string
			tag      *string
			limit    int
			err      error
		)
		qp := r.URL.Query()
		q = qp.Get("q")
		if q == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("q", "query string"))
		}
		if utf8.RuneCountInString(q) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("q", q, utf8.RuneCountInString(q), 1, true))
		}
		notebookRaw := qp.Get("notebook")
		if notebookRaw != "" {
			notebook = &notebookRaw
		}
		if notebook != nil {
			err = goa.MergeErrors(err, goa.ValidatePattern("notebook", *notebook, "^[a-z0-9][a-z0-9_-]{0,63}$"))
		}
		tagRaw := qp.Get("tag")
		if tagRaw != "" {
			tag = &tagRaw
		}
		{
			limitRaw := qp.Get("limit")
			if limitRaw == "" {
				limit = 20
			} else {
				v, err2 := strconv.ParseInt(limitRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("limit", limitRaw, "integer"))
				}
				limit = int(v)
			}
		}
		if limit < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("limit", limit, 1, true))
		}
		if limit > 200 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("limit", limit, 200, false))
		}
		if err != nil {
			return payload, err
		}
		payload = NewSearchPayload(q, notebook, tag, limit)

		return payload, nil
	}
}

