// marshalNotesNoteSummaryToNoteSummaryResponseBody builds a value of type
// *NoteSummaryResponseBody from a value of type *notes.NoteSummary.
func marshalNotesNoteSummaryToNoteSummaryResponseBody(v *notes.NoteSummary) *NoteSummaryResponseBody {
	res := &NoteSummaryResponseBody{
		ID:              v.ID,
		Notebook:        v.Notebook,
		Title:           v.Title,
		CreatedAt:       v.CreatedAt,
		UpdatedAt:       v.UpdatedAt,
		TrashedNotebook: v.TrashedNotebook,
		CreatedBy:       v.CreatedBy,
		Snippet:         v.Snippet,
	}
	if v.Tags != nil {
		res.Tags = make([]string, len(v.Tags))
		for i, val := range v.Tags {
			res.Tags[i] = val
		}
	} else {
		res.Tags = []string{}
	}
	if v.TitleHighlights != nil {
		res.TitleHighlights = make([]*TextRangeResponseBody, len(v.TitleHighlights))
		for i, val := range v.TitleHighlights {
			if val == nil {
				res.TitleHighlights[i] = nil
				continue
			}
			res.TitleHighlights[i] = marshalNotesTextRangeToTextRangeResponseBody(val)
		}
	}
	if v.SnippetHighlights != nil {
		res.SnippetHighlights = make([]*TextRangeResponseBody, len(v.SnippetHighlights))
		for i, val := range v.SnippetHighlights {
			if val == nil {
				res.SnippetHighlights[i] = nil
				continue
			}
			res.SnippetHighlights[i] = marshalNotesTextRangeToTextRangeResponseBody(val)
		}
	}

	return res
}

